#include "complex_numbers.h"

#include <cmath>

namespace complex_numbers {

Complex::Complex(double real, double imag) : real_(real), imag_(imag) {}

double Complex::real() const {
    return real_;
}

double Complex::imag() const {
    return imag_;
}

Complex Complex::conj() const {
    return Complex(real_, -imag_);
}

double Complex::abs() const {
    return std::sqrt(real_ * real_ + imag_ * imag_);
}

Complex Complex::exp() const {
    const double magnitude = std::exp(real_);
    return Complex(magnitude * std::cos(imag_), magnitude * std::sin(imag_));
}

Complex Complex::operator+(const Complex& rhs) const {
    return Complex(real_ + rhs.real_, imag_ + rhs.imag_);
}

Complex Complex::operator-(const Complex& rhs) const {
    return Complex(real_ - rhs.real_, imag_ - rhs.imag_);
}

Complex Complex::operator*(const Complex& rhs) const {
    return Complex(real_ * rhs.real_ - imag_ * rhs.imag_,
                   imag_ * rhs.real_ + real_ * rhs.imag_);
}

Complex Complex::operator/(const Complex& rhs) const {
    const double denominator = rhs.real_ * rhs.real_ + rhs.imag_ * rhs.imag_;
    return Complex((real_ * rhs.real_ + imag_ * rhs.imag_) / denominator,
                   (imag_ * rhs.real_ - real_ * rhs.imag_) / denominator);
}

Complex Complex::operator+(double rhs) const {
    return Complex(real_ + rhs, imag_);
}

Complex Complex::operator-(double rhs) const {
    return Complex(real_ - rhs, imag_);
}

Complex Complex::operator*(double rhs) const {
    return Complex(real_ * rhs, imag_ * rhs);
}

Complex Complex::operator/(double rhs) const {
    return Complex(real_ / rhs, imag_ / rhs);
}

Complex operator+(double lhs, const Complex& rhs) {
    return Complex(lhs + rhs.real(), rhs.imag());
}

Complex operator-(double lhs, const Complex& rhs) {
    return Complex(lhs - rhs.real(), -rhs.imag());
}

Complex operator*(double lhs, const Complex& rhs) {
    return Complex(lhs * rhs.real(), lhs * rhs.imag());
}

Complex operator/(double lhs, const Complex& rhs) {
    return Complex(lhs, 0.0) / rhs;
}

}  // namespace complex_numbers

